{
  "a_sentences": [
    {
      "a_text": "Der Streit dreht sich darum, ob die Vorinstanz den Nichteintretensentscheid der IV-Stelle auf die Neuanmeldung des Versicherten vom 13. März 2024 zu Recht bestätigt hat.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Nach Art. 87 Abs. 2 und 3 IVV ist eine Neuanmeldung nach einem Leistungsverweigerungsentscheid nur zu prüfen, wenn der Versicherte eine anspruchsrelevante Änderung des Invaliditätsgrades plausibel macht.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Diese Anforderung soll die Verwaltung vor unnötigen Nachforschungen bewahren, wenn der Versicherte lediglich die gleichen Argumente wiederholt, ohne eine Veränderung der massgeblichen Tatsachen geltend zu machen.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Im Streit um ein Nichteintreten auf eine Revisionsgesuch ist die gerichtliche Prüfung auf die Frage beschränkt, ob die im Verwaltungsverfahren eingereichten Unterlagen eine Wiederaufnahme der Abklärung rechtfertigen.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Die Vorinstanz verletzte das Recht, indem sie eine anspruchsrelevante Verschlechterung des Gesundheitszustands verneinte, ohne die von der Hausärztin genannten medizinischen Berichte einzuholen.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Das Bundesgericht ordnet an, dass die IV-Stelle die notwendigen medizinischen Auskünfte einholt und über die Neuanmeldung neu entscheidet.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Das Bundesgericht heisst die Beschwerde gut.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Die Sache wird an die IV-Stelle zurückgewiesen, damit sie auf die Neuanmeldung vom 13. März 2024 eintritt.",
      "b_propositions": ["P8"]
    }
  ]
}
